"use strict";
// UI language: picked from the computer's time zone (IANA name reported by the OS through Intl),
// falling back to Chinese. Zones with large Chinese-reading player bases (Singapore, Malaysia)
// deliberately stay on the Chinese fallback. Unit names are game data and are not translated here.
const I18N = (() => {
  const LANGS = [
    { id: "zh", html: "zh-CN", name: "简体中文" },
    { id: "en", html: "en", name: "English" },
    { id: "ja", html: "ja", name: "日本語" },
    { id: "fr", html: "fr", name: "Français" },
    { id: "de", html: "de", name: "Deutsch" },
    { id: "es", html: "es", name: "Español" },
  ];
  const ZONES = {
    zh: ["Asia/Shanghai", "Asia/Chongqing", "Asia/Chungking", "Asia/Harbin", "Asia/Urumqi", "Asia/Kashgar", "Asia/Hong_Kong", "Asia/Macau", "Asia/Macao", "Asia/Taipei", "PRC", "ROC", "Hongkong"],
    ja: ["Asia/Tokyo", "Japan"],
    de: ["Europe/Berlin", "Europe/Busingen", "Europe/Vienna", "Europe/Zurich", "Europe/Vaduz"],
    fr: ["Europe/Paris", "Europe/Monaco", "Europe/Brussels", "Europe/Luxembourg", "America/Montreal", "America/Port-au-Prince", "America/Martinique", "America/Guadeloupe", "America/Cayenne", "America/Miquelon",
      "Indian/Reunion", "Indian/Mayotte", "Indian/Antananarivo", "Indian/Comoro", "Pacific/Tahiti", "Pacific/Noumea", "Pacific/Marquesas", "Pacific/Gambier", "Pacific/Wallis",
      "Africa/Dakar", "Africa/Kinshasa", "Africa/Lubumbashi", "Africa/Brazzaville", "Africa/Libreville", "Africa/Douala", "Africa/Niamey", "Africa/Ndjamena", "Africa/Bamako", "Africa/Ouagadougou",
      "Africa/Conakry", "Africa/Lome", "Africa/Porto-Novo", "Africa/Bangui", "Africa/Djibouti", "Africa/Bujumbura"],
    es: ["Europe/Madrid", "Africa/Ceuta", "Atlantic/Canary", "Africa/Malabo", "America/Mexico_City", "America/Cancun", "America/Merida", "America/Monterrey", "America/Matamoros", "America/Chihuahua",
      "America/Ciudad_Juarez", "America/Ojinaga", "America/Mazatlan", "America/Bahia_Banderas", "America/Hermosillo", "America/Tijuana", "America/Guatemala", "America/El_Salvador", "America/Tegucigalpa",
      "America/Managua", "America/Costa_Rica", "America/Panama", "America/Havana", "America/Santo_Domingo", "America/Puerto_Rico", "America/Bogota", "America/Caracas", "America/Guayaquil",
      "Pacific/Galapagos", "America/Lima", "America/La_Paz", "America/Santiago", "America/Punta_Arenas", "Pacific/Easter", "America/Asuncion", "America/Montevideo", "America/Buenos_Aires", "America/Cordoba"],
    en: ["America/New_York", "America/Chicago", "America/Denver", "America/Los_Angeles", "America/Phoenix", "America/Anchorage", "America/Juneau", "America/Adak", "America/Boise", "America/Detroit",
      "America/Toronto", "America/Vancouver", "America/Edmonton", "America/Winnipeg", "America/Halifax", "America/St_Johns", "America/Regina", "America/Moncton", "America/Whitehorse", "America/Jamaica",
      "America/Nassau", "America/Barbados", "America/Port_of_Spain", "America/Belize", "America/Guyana", "Atlantic/Bermuda", "Pacific/Honolulu", "Pacific/Auckland", "Pacific/Chatham", "Pacific/Guam",
      "Pacific/Fiji", "Europe/London", "Europe/Dublin", "Europe/Isle_of_Man", "Europe/Jersey", "Europe/Guernsey", "Europe/Gibraltar", "Asia/Kolkata", "Asia/Calcutta", "Asia/Manila",
      "Africa/Johannesburg", "Africa/Lagos", "Africa/Nairobi", "Africa/Accra", "Africa/Harare", "Africa/Lusaka", "Africa/Kampala", "Africa/Dar_es_Salaam", "Africa/Gaborone", "Africa/Windhoek"],
  };
  const PREFIXES = [["America/Argentina/", "es"], ["America/Indiana/", "en"], ["America/Kentucky/", "en"], ["America/North_Dakota/", "en"], ["Australia/", "en"], ["US/", "en"], ["Canada/", "en"]];
  const dict = {};
  let current = "zh";

  function langForZone(tz) {
    if (!tz) return "zh";
    for (const [lang, zones] of Object.entries(ZONES)) if (zones.includes(tz)) return lang;
    for (const [prefix, lang] of PREFIXES) if (tz.startsWith(prefix)) return lang;
    return "zh";
  }
  function detect() {
    let tz = "";
    try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ""; } catch { /* very old engines */ }
    return { tz, lang: langForZone(tz) };
  }
  const locale = () => LANGS.find(l => l.id === current).html;
  // Strings may be { one, other } (CLDR plural categories); {name} slots are filled only when params are given.
  function t(key, params) {
    let entry = dict[current]?.[key] ?? dict.zh[key] ?? key;
    if (entry && typeof entry === "object") entry = entry[new Intl.PluralRules(locale()).select(params?.n ?? 0)] ?? entry.other;
    return params ? entry.replace(/\{(\w+)\}/g, (m, k) => (params[k] ?? m)) : entry;
  }
  return {
    LANGS,
    detect,
    langForZone,
    t,
    locale,
    add(lang, strings) { dict[lang] = strings; },
    set(lang) { current = dict[lang] ? lang : "zh"; },
    has: lang => !!dict[lang],
    keys: lang => Object.keys(dict[lang] || {}),
    get lang() { return current; },
  };
})();

